  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
.font-display {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.text-red {
  color: var(--red);
}

/* =========================
   Top Promo Bar
   ========================= */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.05em;
