}

.promo-bar a {
  text-decoration: underline;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}

.promo-bar a:hover {
  opacity: 0.8;
}

/* =========================
   Navigation
   ========================= */
.nav-wrapper {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}

.nav-inner {
  max-width: 1320px;
