  font-size: 0.95rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: all var(--transition-fast);
}

.schedule-table tr:hover td {
  background: var(--bg-card);
  color: var(--text-primary);
}

.schedule-table td:first-child {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

/* =========================
   Instructor Grid
   ========================= */
.filter-bar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.filter-btn {
  padding: 10px 22px;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text-primary);
}

.filter-btn:hover:not(.active) {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-normal);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}

.instructor-card-img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  filter: grayscale(30%);
  transition: filter var(--transition-normal);
}

.instructor-card:hover .instructor-card-img {
  filter: grayscale(0%);
}

.instructor-card-body {
  padding: 20px;
}

.instructor-card-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.instructor-card-location {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.instructor-card-link {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  transition: opacity var(--transition-fast);
}

.instructor-card-link:hover {
  opacity: 0.8;
}

.instructor-card.hidden {
  display: none;
}

/* =========================
   FAQ Accordion
   ========================= */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--red);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-icon::before,
.faq-icon::after {
  content: '';
  position: absolute;
  background: var(--red);
  transition: transform var(--transition-normal);
}

.faq-icon::before {
  top: 50%;
  left: 2px;
  right: 2px;
  height: 2px;
  transform: translateY(-50%);
}

.faq-icon::after {
  left: 50%;
  top: 2px;
  bottom: 2px;
  width: 2px;
  transform: translateX(-50%);
}

.faq-item.open .faq-icon::after {
  transform: translateX(-50%) rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* =========================
   Digital Platform Features
   ========================= */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 36px 28px;
  transition: all var(--transition-normal);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230, 57, 70, 0.12);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--red);
}

.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* =========================
   Unlimited Access / CTA Section
   ========================= */
.cta-section {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section .red-glow {
  position: absolute;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, var(--red-glow) 0%, transparent 70%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* =========================
   Responsive
   ========================= */
@media (max-width: 1024px) {
  .nav-links {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .nav-utility {
    display: none;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-slide {
    min-width: 33.333%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .section {
    padding: 64px 16px;
  }

  .hero {
    min-height: 70vh;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .carousel-slide {
    min-width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .filter-bar {
    overflow-x: auto;
    flex-wrap: nowrap;
    -webkit-overflow-scrolling: touch;
  }

  .filter-btn {
    flex-shrink: 0;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 12px 14px;
    font-size: 0.85rem;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 0.8rem;
  }
}
