/* ============================================
   RedRoom Fitness — Shared Styles
   ============================================ */

/* CSS Custom Properties */
:root {
  --red: #E63946;
  --red-dark: #C62828;
  --red-glow: rgba(230, 57, 70, 0.4);
  --bg-primary: #111111;
  --bg-secondary: #1A1A1A;
  --bg-card: #1E1E1E;
  --bg-card-hover: #252525;
  --text-primary: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border-color: #2A2A2A;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 400ms ease-out;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
.font-display {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.text-red {
  color: var(--red);
}

/* =========================
   Top Promo Bar
   ========================= */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 100;
}

.promo-bar a {
  text-decoration: underline;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}

.promo-bar a:hover {
  opacity: 0.8;
}

/* =========================
   Navigation
   ========================= */
.nav-wrapper {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}

.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  white-space: nowrap;
}

.nav-logo span {
  color: var(--text-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-utility a {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-utility a:hover {
  color: var(--text-primary);
}

.btn-book-nav {
  background: var(--red);
  color: var(--text-primary);
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.btn-book-nav:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-normal);
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: fixed;
  top: 70px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 89;
  padding: 24px;
  overflow-y: auto;
}

.mobile-menu.active {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 16px 0;
  font-size: 1.1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: color var(--transition-fast);
}

.mobile-menu a:hover {
  color: var(--text-primary);
}

/* =========================
   Hero Section
   ========================= */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.3);
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.6) 0%, rgba(17,17,17,0.9) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.05;
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.6;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* =========================
   Buttons
   ========================= */
.btn-primary {
  display: inline-block;
  background: var(--red);
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
}

.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}

.btn-outline {
  display: inline-block;
  background: transparent;
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  border: 2px solid var(--text-primary);
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  background: var(--text-primary);
  color: var(--bg-primary);
}

.btn-lg {
  padding: 20px 48px;
  font-size: 1.1rem;
}

/* =========================
   Section Styles
   ========================= */
.section {
  padding: 100px 24px;
}

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.text-center {
  text-align: center;
}

/* =========================
   Community Promo
   ========================= */
.community-promo {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

/* =========================
   Two Ways Cards
   ========================= */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 48px;
}

.two-ways-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 48px 36px;
  transition: border-color var(--transition-normal), transform var(--transition-normal);
  position: relative;
  overflow: hidden;
}

.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition-slow);
}

.two-ways-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.two-ways-card:hover::before {
  transform: scaleX(1);
}

.two-ways-card .label {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--red);
  margin-bottom: 16px;
}

.two-ways-card h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.two-ways-card p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* =========================
   Studio Experience
   ========================= */
.studio-experience {
  position: relative;
  overflow: hidden;
}

.studio-experience-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.2);
}

.studio-experience .section-inner {
  position: relative;
  z-index: 2;
}

/* =========================
   Free Trial CTA
   ========================= */
.free-trial-cta {
  background: var(--red);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.free-trial-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(255,255,255,0.05) 0%, transparent 70%);
}

.free-trial-cta .section-title {
  color: var(--text-primary);
}

.free-trial-cta .btn-primary {
  background: var(--text-primary);
  color: var(--bg-primary);
}

.free-trial-cta .btn-primary:hover {
  background: #ddd;
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* =========================
   Lifestyle Carousel
   ========================= */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.carousel-slide {
  min-width: 25%;
  padding: 0 8px;
}

.carousel-slide img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 6px;
  transition: transform var(--transition-normal);
}

.carousel-slide img:hover {
  transform: scale(1.03);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(17, 17, 17, 0.85);
  border: 1px solid var(--border-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  font-size: 1.2rem;
  z-index: 10;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn.prev {
  left: 16px;
}

.carousel-btn.next {
  right: 16px;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.carousel-dot.active {
  background: var(--red);
}

/* =========================
   Newsletter
   ========================= */
.newsletter {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}

.newsletter-input-wrapper {
  flex: 1;
  position: relative;
}

.newsletter-input {
  width: 100%;
  padding: 14px 18px;
  background: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 0.95rem;
  font-family: var(--font-body);
  transition: border-color var(--transition-fast);
  outline: none;
}

.newsletter-input::placeholder {
  color: var(--text-muted);
}

.newsletter-input:focus {
  border-color: var(--red);
}

.newsletter-input.error {
  border-color: #ff4444;
}

.newsletter-input.success {
  border-color: #44ff44;
}

.newsletter-msg {
  position: absolute;
  bottom: -24px;
  left: 0;
  font-size: 0.8rem;
  font-weight: 500;
}

.newsletter-msg.error {
  color: #ff4444;
}

.newsletter-msg.success {
  color: #44ff44;
}

.newsletter-btn {
  padding: 14px 28px;
  background: var(--red);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
  white-space: nowrap;
}

.newsletter-btn:hover {
  background: var(--red-dark);
}

/* =========================
   Footer
   ========================= */
.site-footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 24px;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.footer-country {
  position: relative;
}

.footer-country-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.footer-country-btn:hover {
  border-color: var(--text-muted);
}

.footer-country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  min-width: 160px;
  overflow: hidden;
  box-shadow: 0 -8px 30px rgba(0,0,0,0.4);
}

.footer-country-dropdown.active {
  display: block;
}

.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 0.85rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.footer-country-dropdown a:hover {
  background: var(--bg-card-hover);
  color: var(--text-primary);
}

/* =========================
   Workout Page — Toggle
   ========================= */
.toggle-wrapper {
  display: inline-flex;
  background: var(--bg-card);
  border-radius: 6px;
  border: 1px solid var(--border-color);
  overflow: hidden;
}

.toggle-btn {
  padding: 14px 32px;
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background: var(--red);
  color: var(--text-primary);
}

.toggle-btn:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* =========================
   Weekly Schedule Table
   ========================= */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 32px;
}

.schedule-table th {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  padding: 16px 20px;
  text-align: left;
  border-bottom: 2px solid var(--red);
}

.schedule-table td {
  padding: 16px 20px;
  font-size: 0.95rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: all var(--transition-fast);
}

.schedule-table tr:hover td {
  background: var(--bg-card);
  color: var(--text-primary);
}

.schedule-table td:first-child {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

/* =========================
   Instructor Grid
   ========================= */
.filter-bar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.filter-btn {
  padding: 10px 22px;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text-primary);
}

.filter-btn:hover:not(.active) {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-normal);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}

.instructor-card-img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  filter: grayscale(30%);
  transition: filter var(--transition-normal);
}

.instructor-card:hover .instructor-card-img {
  filter: grayscale(0%);
}

.instructor-card-body {
  padding: 20px;
}

.instructor-card-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.instructor-card-location {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.instructor-card-link {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  transition: opacity var(--transition-fast);
}

.instructor-card-link:hover {
  opacity: 0.8;
}

.instructor-card.hidden {
  display: none;
}

/* =========================
   FAQ Accordion
   ========================= */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--red);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-icon::before,
.faq-icon::after {
  content: '';
  position: absolute;
  background: var(--red);
  transition: transform var(--transition-normal);
}

.faq-icon::before {
  top: 50%;
  left: 2px;
  right: 2px;
  height: 2px;
  transform: translateY(-50%);
}

.faq-icon::after {
  left: 50%;
  top: 2px;
  bottom: 2px;
  width: 2px;
  transform: translateX(-50%);
}

.faq-item.open .faq-icon::after {
  transform: translateX(-50%) rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* =========================
   Digital Platform Features
   ========================= */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 36px 28px;
  transition: all var(--transition-normal);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230, 57, 70, 0.12);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--red);
}

.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* =========================
   Unlimited Access / CTA Section
   ========================= */
.cta-section {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section .red-glow {
  position: absolute;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, var(--red-glow) 0%, transparent 70%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* =========================
   Responsive
   ========================= */
@media (max-width: 1024px) {
  .nav-links {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .nav-utility {
    display: none;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-slide {
    min-width: 33.333%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .section {
    padding: 64px 16px;
  }

  .hero {
    min-height: 70vh;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .carousel-slide {
    min-width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .filter-bar {
    overflow-x: auto;
    flex-wrap: nowrap;
    -webkit-overflow-scrolling: touch;
  }

  .filter-btn {
    flex-shrink: 0;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 12px 14px;
    font-size: 0.85rem;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 0.8rem;
  }
}

/* ============================================
   RedRoom Fitness — Shared Styles
   ============================================ */

/* CSS Custom Properties */
:root {
  --red: #E63946;
  --red-dark: #C62828;
  --red-glow: rgba(230, 57, 70, 0.4);
  --bg-primary: #111111;
  --bg-secondary: #1A1A1A;
  --bg-card: #1E1E1E;
  --bg-card-hover: #252525;
  --text-primary: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border-color: #2A2A2A;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 400ms ease-out;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
.font-display {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.text-red {
  color: var(--red);
}

/* =========================
   Top Promo Bar
   ========================= */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 100;
}

.promo-bar a {
  text-decoration: underline;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}

.promo-bar a:hover {
  opacity: 0.8;
}

/* =========================
   Navigation
   ========================= */
.nav-wrapper {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}

.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  white-space: nowrap;
}

.nav-logo span {
  color: var(--text-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-utility a {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-utility a:hover {
  color: var(--text-primary);
}

.btn-book-nav {
  background: var(--red);
  color: var(--text-primary);
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.btn-book-nav:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-normal);
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: fixed;
  top: 70px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 89;
  padding: 24px;
  overflow-y: auto;
}

.mobile-menu.active {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 16px 0;
  font-size: 1.1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: color var(--transition-fast);
}

.mobile-menu a:hover {
  color: var(--text-primary);
}

/* =========================
   Hero Section
   ========================= */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.3);
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.6) 0%, rgba(17,17,17,0.9) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.05;
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.6;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* =========================
   Buttons
   ========================= */
.btn-primary {
  display: inline-block;
  background: var(--red);
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
}

.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}

.btn-outline {
  display: inline-block;
  background: transparent;
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  border: 2px solid var(--text-primary);
  transition: all var(--transition-fast);
}

.btn-outline:hover {
  background: var(--text-primary);
  color: var(--bg-primary);
}

.btn-lg {
  padding: 20px 48px;
  font-size: 1.1rem;
}

/* =========================
   Section Styles
   ========================= */
.section {
  padding: 100px 24px;
}

.section-inner {
  max-width: 1200px;
  margin: 0 auto;
}

.section-title {
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 20px;
}

.section-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  max-width: 640px;
  line-height: 1.7;
}

.section-subtitle.centered {
  margin-left: auto;
  margin-right: auto;
  text-align: center;
}

.text-center {
  text-align: center;
}

/* =========================
   Community Promo
   ========================= */
.community-promo {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
}

/* =========================
   Two Ways Cards
   ========================= */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
  margin-top: 48px;
}

.two-ways-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 48px 36px;
  transition: border-color var(--transition-normal), transform var(--transition-normal);
  position: relative;
  overflow: hidden;
}

.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition-slow);
}

.two-ways-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.two-ways-card:hover::before {
  transform: scaleX(1);
}

.two-ways-card .label {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--red);
  margin-bottom: 16px;
}

.two-ways-card h3 {
  font-family: var(--font-display);
  font-size: 1.8rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.two-ways-card p {
  color: var(--text-secondary);
  line-height: 1.7;
}

/* =========================
   Studio Experience
   ========================= */
.studio-experience {
  position: relative;
  overflow: hidden;
}

.studio-experience-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.2);
}

.studio-experience .section-inner {
  position: relative;
  z-index: 2;
}

/* =========================
   Free Trial CTA
   ========================= */
.free-trial-cta {
  background: var(--red);
  text-align: center;
  position: relative;
  overflow: hidden;
}

.free-trial-cta::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(255,255,255,0.05) 0%, transparent 70%);
}

.free-trial-cta .section-title {
  color: var(--text-primary);
}

.free-trial-cta .btn-primary {
  background: var(--text-primary);
  color: var(--bg-primary);
}

.free-trial-cta .btn-primary:hover {
  background: #ddd;
  box-shadow: 0 8px 30px rgba(0,0,0,0.3);
}

/* =========================
   Lifestyle Carousel
   ========================= */
.carousel-container {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.25, 0.46, 0.45, 0.94);
}

.carousel-slide {
  min-width: 25%;
  padding: 0 8px;
}

.carousel-slide img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  border-radius: 6px;
  transition: transform var(--transition-normal);
}

.carousel-slide img:hover {
  transform: scale(1.03);
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 48px;
  height: 48px;
  background: rgba(17, 17, 17, 0.85);
  border: 1px solid var(--border-color);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
  font-size: 1.2rem;
  z-index: 10;
  transition: all var(--transition-fast);
  cursor: pointer;
}

.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}

.carousel-btn.prev {
  left: 16px;
}

.carousel-btn.next {
  right: 16px;
}

.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
}

.carousel-dot.active {
  background: var(--red);
}

/* =========================
   Newsletter
   ========================= */
.newsletter {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border-color);
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 480px;
  margin: 0 auto;
  position: relative;
}

.newsletter-input-wrapper {
  flex: 1;
  position: relative;
}

.newsletter-input {
  width: 100%;
  padding: 14px 18px;
  background: var(--bg-card);
  border: 2px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-primary);
  font-size: 0.95rem;
  font-family: var(--font-body);
  transition: border-color var(--transition-fast);
  outline: none;
}

.newsletter-input::placeholder {
  color: var(--text-muted);
}

.newsletter-input:focus {
  border-color: var(--red);
}

.newsletter-input.error {
  border-color: #ff4444;
}

.newsletter-input.success {
  border-color: #44ff44;
}

.newsletter-msg {
  position: absolute;
  bottom: -24px;
  left: 0;
  font-size: 0.8rem;
  font-weight: 500;
}

.newsletter-msg.error {
  color: #ff4444;
}

.newsletter-msg.success {
  color: #44ff44;
}

.newsletter-btn {
  padding: 14px 28px;
  background: var(--red);
  color: var(--text-primary);
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  border: none;
  cursor: pointer;
  transition: background var(--transition-fast);
  white-space: nowrap;
}

.newsletter-btn:hover {
  background: var(--red-dark);
}

/* =========================
   Footer
   ========================= */
.site-footer {
  background: var(--bg-primary);
  border-top: 1px solid var(--border-color);
  padding: 60px 24px 24px;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 40px;
  margin-bottom: 48px;
}

.footer-col h4 {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--red);
  margin-bottom: 20px;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  max-width: 1200px;
  margin: 0 auto;
  padding-top: 24px;
  border-top: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.footer-country {
  position: relative;
}

.footer-country-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-secondary);
  font-size: 0.85rem;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.footer-country-btn:hover {
  border-color: var(--text-muted);
}

.footer-country-dropdown {
  display: none;
  position: absolute;
  bottom: 100%;
  left: 0;
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  min-width: 160px;
  overflow: hidden;
  box-shadow: 0 -8px 30px rgba(0,0,0,0.4);
}

.footer-country-dropdown.active {
  display: block;
}

.footer-country-dropdown a {
  display: block;
  padding: 10px 16px;
  font-size: 0.85rem;
  color: var(--text-secondary);
  transition: all var(--transition-fast);
}

.footer-country-dropdown a:hover {
  background: var(--bg-card-hover);
  color: var(--text-primary);
}

/* =========================
   Workout Page — Toggle
   ========================= */
.toggle-wrapper {
  display: inline-flex;
  background: var(--bg-card);
  border-radius: 6px;
  border: 1px solid var(--border-color);
  overflow: hidden;
}

.toggle-btn {
  padding: 14px 32px;
  font-family: var(--font-display);
  font-size: 0.9rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  background: transparent;
  border: none;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.toggle-btn.active {
  background: var(--red);
  color: var(--text-primary);
}

.toggle-btn:hover:not(.active) {
  color: var(--text-primary);
}

.toggle-content {
  display: none;
  animation: fadeIn 0.3s ease-out;
}

.toggle-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* =========================
   Weekly Schedule Table
   ========================= */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 32px;
}

.schedule-table th {
  font-family: var(--font-display);
  font-size: 0.85rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  padding: 16px 20px;
  text-align: left;
  border-bottom: 2px solid var(--red);
}

.schedule-table td {
  padding: 16px 20px;
  font-size: 0.95rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: all var(--transition-fast);
}

.schedule-table tr:hover td {
  background: var(--bg-card);
  color: var(--text-primary);
}

.schedule-table td:first-child {
  font-family: var(--font-display);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--text-primary);
}

/* =========================
   Instructor Grid
   ========================= */
.filter-bar {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 40px;
}

.filter-btn {
  padding: 10px 22px;
  font-family: var(--font-display);
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-btn.active {
  background: var(--red);
  border-color: var(--red);
  color: var(--text-primary);
}

.filter-btn:hover:not(.active) {
  border-color: var(--text-muted);
  color: var(--text-primary);
}

.instructor-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.instructor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  overflow: hidden;
  transition: all var(--transition-normal);
}

.instructor-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  box-shadow: 0 12px 40px rgba(0,0,0,0.3);
}

.instructor-card-img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  filter: grayscale(30%);
  transition: filter var(--transition-normal);
}

.instructor-card:hover .instructor-card-img {
  filter: grayscale(0%);
}

.instructor-card-body {
  padding: 20px;
}

.instructor-card-name {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 4px;
}

.instructor-card-location {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-bottom: 14px;
}

.instructor-card-link {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--red);
  transition: opacity var(--transition-fast);
}

.instructor-card-link:hover {
  opacity: 0.8;
}

.instructor-card.hidden {
  display: none;
}

/* =========================
   FAQ Accordion
   ========================= */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--border-color);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: var(--text-primary);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color var(--transition-fast);
}

.faq-question:hover {
  color: var(--red);
}

.faq-icon {
  width: 24px;
  height: 24px;
  position: relative;
  flex-shrink: 0;
  margin-left: 16px;
}

.faq-icon::before,
.faq-icon::after {
  content: '';
  position: absolute;
  background: var(--red);
  transition: transform var(--transition-normal);
}

.faq-icon::before {
  top: 50%;
  left: 2px;
  right: 2px;
  height: 2px;
  transform: translateY(-50%);
}

.faq-icon::after {
  left: 50%;
  top: 2px;
  bottom: 2px;
  width: 2px;
  transform: translateX(-50%);
}

.faq-item.open .faq-icon::after {
  transform: translateX(-50%) rotate(90deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-answer-inner {
  padding-bottom: 24px;
  color: var(--text-secondary);
  line-height: 1.7;
  font-size: 0.95rem;
}

/* =========================
   Digital Platform Features
   ========================= */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-top: 48px;
}

.feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 36px 28px;
  transition: all var(--transition-normal);
}

.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
}

.feature-icon {
  width: 48px;
  height: 48px;
  background: rgba(230, 57, 70, 0.12);
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--red);
}

.feature-card h3 {
  font-family: var(--font-display);
  font-size: 1.1rem;
  font-weight: 700;
  text-transform: uppercase;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.9rem;
  line-height: 1.6;
}

/* =========================
   Unlimited Access / CTA Section
   ========================= */
.cta-section {
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-section .red-glow {
  position: absolute;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, var(--red-glow) 0%, transparent 70%);
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  pointer-events: none;
}

/* =========================
   Responsive
   ========================= */
@media (max-width: 1024px) {
  .nav-links {
    display: none;
  }

  .menu-toggle {
    display: flex;
  }

  .nav-utility {
    display: none;
  }

  .two-ways-grid {
    grid-template-columns: 1fr;
  }

  .instructor-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .features-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .carousel-slide {
    min-width: 33.333%;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .section {
    padding: 64px 16px;
  }

  .hero {
    min-height: 70vh;
  }

  .hero-ctas {
    flex-direction: column;
    align-items: center;
  }

  .instructor-grid {
    grid-template-columns: 1fr;
  }

  .features-grid {
    grid-template-columns: 1fr;
  }

  .carousel-slide {
    min-width: 100%;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .newsletter-form {
    flex-direction: column;
  }

  .filter-bar {
    overflow-x: auto;
    flex-wrap: nowrap;
    -webkit-overflow-scrolling: touch;
  }

  .filter-btn {
    flex-shrink: 0;
  }

  .schedule-table th,
  .schedule-table td {
    padding: 12px 14px;
    font-size: 0.85rem;
  }

  .toggle-btn {
    padding: 12px 20px;
    font-size: 0.8rem;
  }
}

raw_arguments.content:
/* ============================================
   RedRoom Fitness — Shared Styles
   ============================================ */

/* CSS Custom Properties */
:root {
  --red: #E63946;
  --red-dark: #C62828;
  --red-glow: rgba(230, 57, 70, 0.4);
  --bg-primary: #111111;
  --bg-secondary: #1A1A1A;
  --bg-card: #1E1E1E;
  --bg-card-hover: #252525;
  --text-primary: #FFFFFF;
  --text-secondary: #B0B0B0;
  --text-muted: #777777;
  --border-color: #2A2A2A;
  --font-display: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --transition-fast: 150ms ease;
  --transition-normal: 250ms ease;
  --transition-slow: 400ms ease-out;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

img {
  max-width: 100%;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
  color: inherit;
}

/* Typography */
.font-display {
  font-family: var(--font-display);
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.text-red {
  color: var(--red);
}

/* =========================
   Top Promo Bar
   ========================= */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 16px;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  position: relative;
  z-index: 100;
}

.promo-bar a {
  text-decoration: underline;
  margin-left: 8px;
  transition: opacity var(--transition-fast);
}

.promo-bar a:hover {
  opacity: 0.8;
}

/* =========================
   Navigation
   ========================= */
.nav-wrapper {
  position: sticky;
  top: 0;
  z-index: 90;
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
}

.nav-inner {
  max-width: 1320px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 70px;
}

.nav-logo {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--red);
  white-space: nowrap;
}

.nav-logo span {
  color: var(--text-primary);
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 28px;
  list-style: none;
}

.nav-links a {
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
  white-space: nowrap;
}

.nav-links a:hover,
.nav-links a.active {
  color: var(--text-primary);
}

.nav-utility {
  display: flex;
  align-items: center;
  gap: 20px;
}

.nav-utility a {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.nav-utility a:hover {
  color: var(--text-primary);
}

.btn-book-nav {
  background: var(--red);
  color: var(--text-primary);
  padding: 10px 20px;
  border-radius: 4px;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.btn-book-nav:hover {
  background: var(--red-dark);
  transform: translateY(-1px);
}

/* Mobile Menu Toggle */
.menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--text-primary);
  transition: all var(--transition-normal);
}

.menu-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.menu-toggle.active span:nth-child(2) {
  opacity: 0;
}

.menu-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  position: fixed;
  top: 70px;
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--bg-primary);
  z-index: 89;
  padding: 24px;
  overflow-y: auto;
}

.mobile-menu.active {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 16px 0;
  font-size: 1.1rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-color);
  transition: color var(--transition-fast);
}

.mobile-menu a:hover {
  color: var(--text-primary);
}

/* =========================
   Hero Section
   ========================= */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  filter: brightness(0.3);
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(17,17,17,0.6) 0%, rgba(17,17,17,0.9) 100%);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 40px 24px;
}

.hero-title {
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  line-height: 1.05;
  margin-bottom: 20px;
}

.hero-subtitle {
  font-size: 1.1rem;
  color: var(--text-secondary);
  margin-bottom: 32px;
  line-height: 1.6;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* =========================
   Buttons
   ========================= */
.btn-primary {
  display: inline-block;
  background: var(--red);
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  transition: background var(--transition-fast), transform var(--transition-fast), box-shadow var(--transition-fast);
}

.btn-primary:hover {
  background: var(--red-dark);
  transform: translateY(-2px);
  box-shadow: 0 8px 30px var(--red-glow);
}

.btn-outline {
  display: inline-block;
  background: transparent;
  color: var(--text-primary);
  padding: 16px 36px;
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  border-radius: 4px;
  border: 2px solid var(--text-primary);
