  <script>
    // Mobile Menu
    function toggleMobileMenu() {
      const menu = document.getElementById('mobileMenu');
      const toggle = document.querySelector('.menu-toggle');
      menu.classList.toggle('active');
      toggle.classList.toggle('active');
    }

    // Carousel
    let carouselIndex = 0;
    const track = document.getElementById('carouselTrack');
    const slides = track.querySelectorAll('.carousel-slide');

    function getVisibleCount() {
      if (window.innerWidth <= 640) return 1;
      if (window.innerWidth <= 1024) return 3;
      return 4;
    }

    function getMaxIndex() {
      return Math.max(0, slides.length - getVisibleCount());
    }

    function updateCarousel() {
      const visible = getVisibleCount();
      const slideWidth = 100 / visible;
      track.style.transform = `translateX(-${carouselIndex * slideWidth}%)`;
      updateDots();
    }

    function carouselNext() {
      carouselIndex = carouselIndex >= getMaxIndex() ? 0 : carouselIndex + 1;
      updateCarousel();
    }

    function carouselPrev() {
      carouselIndex = carouselIndex <= 0 ? getMaxIndex() : carouselIndex - 1;
      updateCarousel();
    }

    function updateDots() {
      const dotsContainer = document.getElementById('carouselDots');
      const maxIdx = getMaxIndex();
      dotsContainer.innerHTML = '';
      for (let i = 0; i <= maxIdx; i++) {
        const dot = document.createElement('button');
        dot.className = 'carousel-dot' + (i === carouselIndex ? ' active' : '');
        dot.onclick = () => { carouselIndex = i; updateCarousel(); };
        dotsContainer.appendChild(dot);
      }
    }

    // Touch/swipe support
    let touchStartX = 0;
    let touchEndX = 0;
    const carouselEl = document.getElementById('carousel');

    carouselEl.addEventListener('touchstart', e => { touchStartX = e.changedTouches[0].screenX; }, { passive: true });
    carouselEl.addEventListener('touchend', e => {
      touchEndX = e.changedTouches[0].screenX;
      const diff = touchStartX - touchEndX;
      if (Math.abs(diff) > 50) {
        if (diff > 0) carouselNext();
        else carouselPrev();
      }
    }, { passive: true });

    window.addEventListener('resize', () => {
      if (carouselIndex > getMaxIndex()) carouselIndex = getMaxIndex();
      updateCarousel();
    });

    updateCarousel();

    // Auto-advance carousel
    let autoSlide = setInterval(carouselNext, 5000);
    carouselEl.addEventListener('mouseenter', () => clearInterval(autoSlide));
    carouselEl.addEventListener('mouseleave', () => { autoSlide = setInterval(carouselNext, 5000); });

    // Newsletter
    function handleNewsletter(e, form) {
      e.preventDefault();
      const input = form.querySelector('.newsletter-input');
      const msg = form.querySelector('.newsletter-msg');
      const email = input.value.trim();
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (!emailRegex.test(email)) {
        input.classList.add('error');
        input.classList.remove('success');
        msg.textContent = 'Please enter a valid email address.';
        msg.className = 'newsletter-msg error';
        return false;
      }

      input.classList.remove('error');
      input.classList.add('success');
      msg.textContent = 'You\'re in! Welcome to the RedRoom community.';
      msg.className = 'newsletter-msg success';
      input.value = '';
      return false;
    }

    // Country Dropdown
    function toggleCountryDropdown() {
      document.getElementById('countryDropdown').classList.toggle('active');
    }

    document.addEventListener('click', (e) => {
      if (!e.target.closest('.footer-country')) {
        document.getElementById('countryDropdown').classList.remove('active');
      }
    });
  </script>

